def apply(inputs, premises):
    answer = {}
    cap = float(premises["per_debtor_other_property_limit"]) * int(inputs["number_of_debtors"])
    n = len(inputs["asset_descriptions"])
    for i in range(n):
        description = inputs["asset_descriptions"][i]
        claims = []
        if bool(inputs["asset_is_personal_nonbusiness_property"][i]):
            if inputs["output_family"] == "EV":
                claim_value = min(float(inputs["asset_values"][i]), cap)
                claims = [{"citation": premises["other_property_citation"], "claim_value": claim_value}]
            else:
                claims = [premises["other_property_citation"]]
        answer[description] = claims
    return {"answer": answer}

def apply(inputs, premises):
    personal_used = False
    carry_used = False
    checked = []
    n = len(inputs["item_lengths"])
    for i in range(n):
        personal_ok = float(inputs["item_lengths"][i]) <= float(premises["personal_item_limits"][0]) and float(inputs["item_widths"][i]) <= float(premises["personal_item_limits"][1]) and float(inputs["item_heights"][i]) <= float(premises["personal_item_limits"][2])
        carry_ok = float(inputs["item_lengths"][i]) <= float(premises["carry_on_limits"][0]) and float(inputs["item_widths"][i]) <= float(premises["carry_on_limits"][1]) and float(inputs["item_heights"][i]) <= float(premises["carry_on_limits"][2])
        if personal_ok and not personal_used:
            personal_used = True
        elif carry_ok and not carry_used:
            carry_used = True
        else:
            checked = checked + [i]
    if inputs["cabin_class"] == "First":
        base_schedule = premises["first_domestic_base_schedule"]
        standard_weight_limit = float(premises["first_standard_weight_limit"])
    else:
        base_schedule = premises["main_domestic_base_schedule"]
        standard_weight_limit = float(premises["main_standard_weight_limit"])
    total = int(inputs["ticket_price"])
    for j in range(len(checked)):
        i = checked[j]
        if j < 4:
            base_fee = int(base_schedule[j])
        else:
            base_fee = int(base_schedule[3])
        weight = float(inputs["item_weights"][i])
        overweight = 0
        if weight > standard_weight_limit:
            if weight <= 53:
                overweight = int(premises["domestic_overweight_fees"][0])
            elif weight <= 70:
                overweight = int(premises["domestic_overweight_fees"][1])
            else:
                overweight = int(premises["domestic_overweight_fees"][2])
        size = float(inputs["item_lengths"][i]) + float(inputs["item_widths"][i]) + float(inputs["item_heights"][i])
        oversize = 0
        if size > 65:
            oversize = int(premises["domestic_oversize_fees"][1])
        elif size > 62:
            oversize = int(premises["domestic_oversize_fees"][0])
        total = total + base_fee + max(overweight, oversize)
    return {"answer": total}

